svg.script:
var doc, scanOptions = { strm: true, subtitle: true, sidecar: false }, diagnosticsOpen = false, advancedOpen = false, addedRule = false, originals = {};
function byId(id) { return doc.getElementById(id); }
function setText(id, value) { byId(id).textContent = value; }
function show(id) { var node = byId(id); node.setAttribute('class', node.getAttribute('class').replace(/\bhidden\b/g, '').trim()); node.setAttribute('display', 'block'); }
function hide(id) { var node = byId(id); if (node.getAttribute('class').indexOf('hidden') < 0) node.setAttribute('class', (node.getAttribute('class') + ' hidden').trim()); node.setAttribute('display', 'none'); }
function toast(message, tone) {
  setText('toast-text', message);
  byId('toast-dot').setAttribute('fill', tone || '#56CA00');
  show('toast');
  clearTimeout(toast.timer);
  toast.timer = setTimeout(function () { hide('toast'); }, 2800);
}
function switchView(view) {
  var dashboard = view === 'dashboard';
  byId('dashboard-view').setAttribute('display', dashboard ? 'block' : 'none');
  byId('config-view').setAttribute('display', dashboard ? 'none' : 'block');
  byId('tab-dashboard').setAttribute('class', 'ui ' + (dashboard ? 'strong tabActive' : 'body tabIdle'));
  byId('tab-config').setAttribute('class', 'ui ' + (dashboard ? 'body tabIdle' : 'strong tabActive'));
  byId('tab-dashboard-line').setAttribute('stroke', dashboard ? '#6E66ED' : 'transparent');
  byId('tab-config-line').setAttribute('stroke', dashboard ? 'transparent' : '#6E66ED');
}
function closeModal() { ['full-scan-modal', 'cleanup-modal', 'details-modal', 'new-rule-modal'].forEach(hide); }
function openModal(id) { closeModal(); show(id); }
function toggleScan(name) {
  scanOptions[name] = !scanOptions[name];
  var box = byId('scan-' + name + '-box'), check = byId('scan-' + name + '-check');
  box.setAttribute('fill', scanOptions[name] ? '#6E66ED' : '#10131A');
  box.setAttribute('stroke', scanOptions[name] ? 'transparent' : '#474A58');
  check.setAttribute('stroke', scanOptions[name] ? '#FFFFFF' : 'transparent');
  var actions = 12480 + (scanOptions.subtitle ? 3012 : 0) + (scanOptions.sidecar ? 3614 : 0);
  setText('action-preview', actions.toLocaleString() + ' 个文件动作');
}
function startScan() {
  closeModal();
  setText('runtime-title', '全量处理正在进行');
  setText('runtime-copy', '正在扫描已启用目录规则 · 已处理 0 / 12,480');
  setText('runtime-chip', '运行中');
  setText('runtime-queue', '队列 1');
  byId('runtime-chip-bg').setAttribute('fill', '#242339');
  byId('runtime-chip-bg').setAttribute('stroke', '#514DB1');
  byId('runtime-chip').setAttribute('class', 'ui small primaryText');
  toast('全量处理已加入队列', '#6E66ED');
  setTimeout(function () {
    setText('runtime-copy', '正在扫描已启用目录规则 · 已处理 1,284 / 12,480');
  }, 900);
}
function retryFailures() {
  setText('failure-count', '0');
  setText('failure-copy', '失败动作已重新加入队列');
  setText('retry-label', '已加入队列');
  setText('runtime-queue', '队列 2');
  toast('2 个失败动作已加入重试队列', '#6E66ED');
}
function confirmCleanup() {
  closeModal();
  setText('cleanup-count', '0');
  setText('cleanup-copy', '清理任务已确认并加入队列');
  setText('runtime-queue', '队列 1');
  toast('36 个候选文件已确认清理', '#FFB400');
}
function refresh() {
  setText('runtime-copy', '当前空闲 · 3 个目录规则 · 最近刷新 刚刚');
  setText('last-checked', '刚刚');
  toast('运行状态已刷新', '#16B1FF');
}
function toggleDiagnostics() {
  diagnosticsOpen = !diagnosticsOpen;
  if (diagnosticsOpen) show('diagnostics'); else hide('diagnostics');
  byId('diagnostics-arrow').setAttribute('d', diagnosticsOpen ? 'M1630 968l7-7 7 7' : 'M1630 961l7 7 7-7');
}
function addRule() { openModal('new-rule-modal'); }
function createRule() {
  var local = byId('new-rule-local').value.trim(), strm = byId('new-rule-strm').value.trim();
  if (!local || !strm) { toast('请填写来源目录和 STRM 生成目录', '#FF4C51'); return; }
  addedRule = true;
  setText('rule-count', '已配置 2 条规则');
  closeModal();
  toast('目录规则已创建，保存配置后生效', '#56CA00');
}
function deleteRule() {
  if (addedRule) {
    addedRule = false;
    setText('rule-count', '已配置 1 条规则');
    toast('新增目录规则已删除', '#FF4C51');
  } else {
    toast('至少保留一条目录规则以继续编辑', '#FFB400');
  }
}
function toggleAdvanced() {
  advancedOpen = !advancedOpen;
  if (advancedOpen) show('advanced-panel'); else hide('advanced-panel');
  setText('advanced-action', advancedOpen ? '点击收起高级设置' : '点击展开高级设置');
  byId('advanced-arrow').setAttribute('d', advancedOpen ? 'M1606 1117l7-7 7 7' : 'M1606 1110l7 7 7-7');
}
function saveConfig() {
  setText('save-state', '配置已保存并生效');
  byId('save-dot').setAttribute('fill', '#56CA00');
  setText('save-time-label', '最近保存 刚刚');
  var enabled = byId('plugin-enabled').checked;
  setText('header-enabled', enabled ? '已启用' : '未启用');
  toast(enabled ? '配置已保存到 MoviePilot' : '配置已保存，插件已停用', enabled ? '#56CA00' : '#FFB400');
}
function resetConfig() {
  var keys = Object.keys(originals);
  for (var i = 0; i < keys.length; i++) {
    var node = byId(keys[i]);
    if (!node) continue;
    if (node.type === 'checkbox') node.checked = originals[keys[i]];
    else node.value = originals[keys[i]];
  }
  setText('save-state', '已恢复为上次保存的配置');
  byId('save-dot').setAttribute('fill', '#16B1FF');
  toast('已恢复上次保存的配置', '#16B1FF');
}
function init(evt) {
  doc = evt.target.ownerDocument;
  var controls = doc.querySelectorAll('input, select');
  for (var i = 0; i < controls.length; i++) {
    if (controls[i].id) originals[controls[i].id] = controls[i].type === 'checkbox' ? controls[i].checked : controls[i].value;
    controls[i].addEventListener('input', function () { setText('save-state', '修改尚未保存'); byId('save-dot').setAttribute('fill', '#FFB400'); });
    controls[i].addEventListener('change', function () { setText('save-state', '修改尚未保存'); byId('save-dot').setAttribute('fill', '#FFB400'); });
  }
  var buttons = doc.querySelectorAll('[data-action]');
  for (var j = 0; j < buttons.length; j++) {
    buttons[j].addEventListener('click', function () {
      var action = this.getAttribute('data-action');
      if (action === 'dashboard' || action === 'config') switchView(action);
      else if (action === 'open-full-scan') openModal('full-scan-modal');
      else if (action === 'toggle-scan-strm') toggleScan('strm');
      else if (action === 'toggle-scan-subtitle') toggleScan('subtitle');
      else if (action === 'toggle-scan-sidecar') toggleScan('sidecar');
      else if (action === 'open-cleanup') openModal('cleanup-modal');
      else if (action === 'details') openModal('details-modal');
      else if (action === 'close-modal') closeModal();
      else if (action === 'start-full-scan') startScan();
      else if (action === 'retry') retryFailures();
      else if (action === 'confirm-cleanup') confirmCleanup();
      else if (action === 'refresh') refresh();
      else if (action === 'toggle-diagnostics') toggleDiagnostics();
      else if (action === 'add-rule') addRule();
      else if (action === 'create-rule') createRule();
      else if (action === 'delete-rule') deleteRule();
      else if (action === 'toggle-advanced') toggleAdvanced();
      else if (action === 'save-config') saveConfig();
      else if (action === 'reset-config') resetConfig();
    });
  }
  doc.addEventListener('keydown', function (event) { if (event.key === 'Escape') closeModal(); });
}
